"""RFC 7807-style reporting for Meridian CRM legacy validation failures."""

from typing import Any

_PROBLEM_TYPE = "https://meridian-crm.example/problems/validation"
_VALID_CODES = frozenset(
    {
        "E1001", "E1002", "E1003", "E1004", "E1005",
        "E2001", "E2002", "E2003", "E2004",
        "E3001", "E3002", "E3003", "E3004", "E3005", "E3006", "E3007",
        "E4001", "E4002", "E4003", "E4004",
        "E5001", "E5002", "E5003", "E5004", "E5005",
    }
)


def problem_details(errors: list[dict]) -> dict:
    """Return a deterministic problem document preserving all failures in order."""
    reported_errors: list[dict[str, Any]] = []
    blocked = False

    for error in errors:
        code = error["code"]
        if code not in _VALID_CODES:
            raise ValueError(f"Unknown legacy validation code: {code!r}")

        severity = error["severity"]
        if severity == "BLOCK":
            blocked = True

        reported_errors.append(
            {
                "code": code,
                "message": error["message"],
                "severity": severity,
            }
        )

    return {
        "type": _PROBLEM_TYPE,
        "title": "Legacy validation failed",
        "status": 422 if blocked else 200,
        "blocked": blocked,
        "errors": reported_errors,
    }
